boolean TraderAnxiety(boolean mktStatus) {<p><pre><code>  if (mktStatus == FALLING) {
    Sell();
    return true;
  }

  if (mktStatus == SURGING) {
    Buy();
    return true;
  }

  if (mktStatus == FEAR) {
    Loathing();
    return true;
  }

  if (mktStatus == OVERMYHEAD) {
    UseProfanity();
    return true;
  }


  return true;</code></pre>
